        my=min(y for y,x in Q); mx=min(x for y,x in Q)
        return frozenset((y-my,x-mx) for y,x in Q)
    def hfl(P):
        Q={(y,-x) for y,x in P}
        my=min(y for y,x in Q); mx=min(x for y,x in Q)
        return frozenset((y-my,x-mx) for y,x in Q)
    cur=pts
    for _ in range(2):
        cur2=hfl(cur)
        if cur2 not in outs: outs[cur2]=cur2
        for _ in range(4):
            cur=rot(cur)
            if cur not in outs: outs[cur]=cur
        cur=rot(cur)
    return list(outs.values())

