def solve(inp):
    I=np.array(inp); H,W=I.shape
    bg=Counter(I.flatten()).most_common(1)[0][0]
    cs=cc(I,bg)
    tinfo=[(c,set(s[1])) for c,s in cs if len(s)>1]
    seeds=[(c,s[0]) for c,s in cs if len(s)==1]
    res=I.copy()
    # place copies in order; allow overlap of newly painted? paint in order, skip occupied-by-original only
    for c,p in seeds:
        # nearest template by min chebyshev dist from seed to any cell of template
        best=None
        for ti,(tc,st) in enumerate(tinfo):
            d=min(max(abs(p[0]-y),abs(p[1]-x)) for (y,x) in st)
            key=(d,ti)
            if best is None or key<best[0]: best=(key,ti)
        tc,st=next((tc,st) for tc,st in tinfo if tinfo.index((tc,st))==best[1])
        rs=min(y for y,x in st); rx=min(x for y,x in st)
        rh=max(y for y,x in st)-rs+1; cw=max(x for y,x in st)-rx+1
        dy = 0 if rs<=p[0]<=max(y for y,x in st) else (-rh if p[0]<rs else rh)
        dx = 0 if rx<=p[1]<=max(x for y,x in st) else (-cw if p[1]<rx else cw)
        copy={(y+dy,x+dx) for y,x in st}
        # orientation variants if the pure translation collides with non-bg input cells or goes out of bounds
        placed=None
        if all(0<=y<H and 0<=x<W for y,x in copy) and all(int(I[y,x])==bg or (y,x) in st for y,x in copy):
            placed=copy
        if placed is None:
            tvs=orient_variants(normshape(st))
            # score variants: try translation (dy,dx) combined with variant, prefer no collision & in bounds
            cand=[]
            for v in tvs:
                hy=max(y for y,x in v)-min(y for y,x in v)+1
                wx=max(x for y,x in v)-min(x for y,x in v)+1
                for sy in(-1,1):
                    for sx_ in(-1,1):
                        dd=-sy*hy; ddx=-sx_*wx
                        q={(y+dd,x+ddx) for y,x in v}
                        if all(0<=y<H and 0<=x<W for y,x in q) and sum(1 for y,x in q if int(I[y,x])!=bg and (y,x) not in set() )==0:
                            coll=sum(1 for y,x in q if int(I[y,x])!=bg)
                            cand.append((coll,len(q),q))
            cand.sort()
            placed=cand[0][2] if cand else copy
        for y,x in placed: res[y,x]=c
    return res.tolist()

