import numpy as np
from collections import Counter
def comps(M,bg):
    M=np.asarray(M);h,w=M.shape;seen=np.zeros_like(M,bool);out=[]
    for i in range(h):
        for j in range(w):
            if not seen[i,j] and M[i,j]!=bg:
                col=int(M[i,j]);q=[(i,j)];seen[i,j]=True;cs=set()
                while q:
                    y,x=q.pop();cs.add((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not seen[ny,nx] and M[ny,nx]==col:
                            seen[ny,nx]=True;q.append((ny,nx))
                out.append((int(col),frozenset(cs)))
    return out
def norm(st): st=list(st); m=min(st); return tuple(sorted((y-m[0],x-m[1]) for y,x in st))
def diheds(st):
    res=[];seen=set();cur=tuple(norm(st))
    def rot(p): return tuple(sorted((x,-y) for y,x in p))
    def mir(p): return tuple(sorted((y,-x) for y,x in p))
    c=cur
    for _ in range(4):
        for v in (c,mir(c)):
            if v not in seen: seen.add(v);res.append(v)
        c=rot(c)
    return res
