        for y in range(H):
            s=0
            for x in range(W):
                s=s+1 if mask[y,x] and (x==0 or mask[y,x-1]) else 0
                if not mask[y,x]: s=0
                hgt[y][x]=s
        prev=hgt.copy()
        best=None
        for y in range(H):
            stack=[]
            for x in range(W+1):
                cur = hgt[y][x] if x<W else 0
                start=x
                while stack and stack[-1][1]>=cur:
                    h0,w0=stack.pop()
                    area=h0*w0
                    # check solidity vertically
                    ok=True
                    for yy in range(y-h0+1,y+1):
                        if any(mask[yy,xx]==0 for xx in range(start,start+w0)): ok=False;break
                    if ok and (best is None or area>best[0]):
